#!/usr/bin/env bash
set -Eeuo pipefail
[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run with sudo/root" >&2; exit 1; }
SID="${1:-25}"
REPO="${2:-/root/hyper-hosting-panel}"
STATE="/var/lib/hyper-cs16/servers/${SID}.json"
ROOT="/srv/hyper-cs16/servers/${SID}"
if [[ -f "$STATE" ]]; then
  ROOT="$(python3 - "$STATE" "$SID" <<'PYROOT'
import json,sys
try:
 d=json.load(open(sys.argv[1],encoding='utf-8')); print(d.get('path') or f'/srv/hyper-cs16/servers/{int(sys.argv[2])}')
except Exception: print(f'/srv/hyper-cs16/servers/{int(sys.argv[2])}')
PYROOT
)"
fi
CS="$ROOT/cstrike"
AMXX="$CS/addons/amxmodx"
PLUGINS="$AMXX/configs/plugins.ini"
SERVICE="hyper-cs16@${SID}.service"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/oldz-fastdl-r10-backup-${SID}-${STAMP}"
URL="http://90.189.208.25/fastdl/${SID}/"
mkdir -p "$BACKUP"
[[ -d "$CS" ]] || { echo "[ERROR] Missing $CS"; exit 2; }
[[ -f "$PLUGINS" ]] || { echo "[ERROR] Missing $PLUGINS"; exit 2; }

echo "================================================================="
echo " OLD ZOMBIE FASTDL RECOVERY R10.1"
echo " Server: #$SID"
echo " cstrike: $CS"
echo " Backup: $BACKUP"
echo "================================================================="
backup_file(){ local f="$1"; [[ -e "$f" ]] || return 0; local rel="${f#/}"; mkdir -p "$BACKUP/$(dirname "$rel")"; cp -a "$f" "$BACKUP/$rel"; }
TIMER_WAS=0
if systemctl is-active --quiet hyper-cs16-fastdl-sync.timer 2>/dev/null; then TIMER_WAS=1; systemctl stop hyper-cs16-fastdl-sync.timer || true; fi
systemctl stop hyper-cs16-fastdl-sync.service 2>/dev/null || true
systemctl stop "$SERVICE" 2>/dev/null || true
cleanup_timer(){ if [[ "$TIMER_WAS" -eq 1 ]]; then systemctl start hyper-cs16-fastdl-sync.timer 2>/dev/null || true; fi; }
trap cleanup_timer EXIT

echo "[1/12] Backups..."
for f in "$PLUGINS" "$AMXX/plugins/oldz_safe_download_r8.amxx" "$AMXX/plugins/oldz_download_guard.amxx" "$AMXX/scripting/oldz_safe_download_r8.sma" "$AMXX/scripting/oldz_download_guard.sma" "$AMXX/plugins/oldz_akblood_vip.amxx" "$AMXX/scripting/oldz_akblood_vip.sma" "$CS/server.cfg" "$CS/fastdl.cfg" "$CS/SAFE_DOWNLOAD_MODE.cfg" "$CS/server_download_fix.cfg" "$CS/ENABLE_FASTDL_AFTER_VERIFY.cfg" "$CS/sound/oldz_admin_r11/balrogm4_fire.wav" "$REPO/cs16-panel/bin/hyper-cs16-ctl" "/usr/local/sbin/hyper-cs16-ctl" "/etc/nginx/hyper-host-managed/00-hyper-cs16-fastdl.conf" "/etc/nginx/conf.d/00-hyper-cs16-fastdl.conf"; do backup_file "$f"; done

echo "[2/12] Disabling stale compiled FastDL killer..."
python3 - "$PLUGINS" <<'PYPLUG'
from pathlib import Path
import sys
p=Path(sys.argv[1]); lines=p.read_text(encoding='utf-8',errors='ignore').splitlines(); out=[]
kill={'oldz_safe_download_r8.amxx','oldz_download_guard.amxx'}; changed=[]
for line in lines:
 st=line.strip(); body=st.lstrip(';').strip(); tok=body.split(';',1)[0].strip().split()[0].lower() if body else ''
 if tok in kill and st and not st.startswith(';'):
  out.append('; HYPER-HOST R10 DISABLED FASTDL KILLER: '+st); changed.append(tok)
 else: out.append(line)
p.write_text('\n'.join(out).rstrip()+'\n',encoding='utf-8')
print('[OK] disabled:', ', '.join(changed) if changed else 'already disabled')
PYPLUG
for n in oldz_safe_download_r8 oldz_download_guard; do
  p="$AMXX/plugins/$n.amxx"; [[ -f "$p" ]] && mv -f "$p" "$p.KILLER_DISABLED_R10"
  cat >"$AMXX/scripting/$n.sma" <<'SMAGUARD'
#include <amxmodx>
public plugin_init() { register_plugin("OLD ZOMBIE FastDL Guard - SAFE", "10.0", "HYPER-HOST"); }
SMAGUARD
done

echo "[3/12] Canonical FastDL cvars..."
python3 - "$CS/server.cfg" "$URL" <<'PYCFG'
from pathlib import Path
import re,sys
p=Path(sys.argv[1]); url=sys.argv[2]; s=p.read_text(encoding='utf-8',errors='ignore') if p.exists() else ''
s=s.replace('\r\n','\n').replace('\r','\n'); s=re.sub(r'(?ims)^\s*// HYPER-HOST FASTDL BEGIN\s*$.*?^\s*// HYPER-HOST FASTDL END\s*$\n?','',s)
managed={'sv_downloadurl','sv_allowdownload','sv_allowupload','sv_send_resources','sv_allow_dlfile'}; out=[]
for line in s.splitlines():
 m=re.match(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s+',line)
 if m and m.group(1).lower() in managed: continue
 out.append(line)
block=['// HYPER-HOST FASTDL BEGIN','// OLD ZOMBIE FASTDL RECOVERY R10.1.1','sv_allowdownload 1','sv_allowupload 0','sv_send_resources 1','sv_allow_dlfile 0',f'sv_downloadurl "{url}"','// HYPER-HOST FASTDL END']
p.write_text('\n'.join(out).rstrip()+'\n\n'+'\n'.join(block)+'\n',encoding='utf-8')
PYCFG
for cfg in fastdl.cfg SAFE_DOWNLOAD_MODE.cfg server_download_fix.cfg ENABLE_FASTDL_AFTER_VERIFY.cfg; do
 [[ -e "$CS/$cfg" ]] || continue
 cat >"$CS/$cfg" <<EOF
// HYPER-HOST R10.1 canonical FastDL
sv_allowdownload 1
sv_allowupload 0
sv_send_resources 1
sv_allow_dlfile 0
sv_downloadurl "$URL"
EOF
done

echo "[4/12] Repairing corrupt skybox/map-description files..."
TMP_PAYLOAD="$(mktemp -d)"
trap 'rm -rf "$TMP_PAYLOAD"; cleanup_timer' EXIT

# R10.1 embeds the three VALID des faces from the user's original img(5).zip.
# The live server may no longer contain them after previous FastDL/import operations,
# so R10's old "use live desbk/desdn/deslf as fallback" was too fragile.
DES_BK=''
DES_DN=''
DES_LF=''

printf '%s' "$DES_BK" | base64 -d >"$TMP_PAYLOAD/desbk.tga"
printf '%s' "$DES_DN" | base64 -d >"$TMP_PAYLOAD/desdn.tga"
printf '%s' "$DES_LF" | base64 -d >"$TMP_PAYLOAD/deslf.tga"

python3 - "$TMP_PAYLOAD" <<'PYTGAVAL'
from pathlib import Path
import sys
root=Path(sys.argv[1])
for p in root.glob('des*.tga'):
    b=p.read_bytes()
    if len(b)<18:
        raise SystemExit(f'[ERROR] embedded TGA too small: {p}')
    if b.lstrip().lower().startswith((b'<!doctype',b'<html')):
        raise SystemExit(f'[ERROR] embedded TGA is HTML: {p}')
    # img(5) originals are 256x256 RGBA TGAs.
    w=int.from_bytes(b[12:14],'little')
    h=int.from_bytes(b[14:16],'little')
    if w!=256 or h!=256:
        raise SystemExit(f'[ERROR] unexpected embedded TGA dimensions {p}: {w}x{h}')
    print('[OK] embedded',p.name,len(b),'bytes',f'{w}x{h}')
PYTGAVAL

mkdir -p "$CS/gfx/env"

# Restore the valid des faces exactly from the user's uploaded build.
install -m 0644 "$TMP_PAYLOAD/desbk.tga" "$CS/gfx/env/desbk.tga"
install -m 0644 "$TMP_PAYLOAD/desdn.tga" "$CS/gfx/env/desdn.tga"
install -m 0644 "$TMP_PAYLOAD/deslf.tga" "$CS/gfx/env/deslf.tga"

# The uploaded build itself contains HTML error pages instead of these 3 faces.
# Use the surviving faces as safe visual fallbacks so GoldSrc receives a real TGA,
# not a 384-byte "Домен не настроен" HTML page.
cp -f "$TMP_PAYLOAD/desbk.tga" "$CS/gfx/env/desft.tga"
cp -f "$TMP_PAYLOAD/deslf.tga" "$CS/gfx/env/desrt.tga"
cp -f "$TMP_PAYLOAD/desdn.tga" "$CS/gfx/env/desup.tga"
cp -f "$CS/gfx/env/desft.tga" "$CS/gfx/env/Desft.tga"
cp -f "$CS/gfx/env/desrt.tga" "$CS/gfx/env/Desrt.tga"
cp -f "$CS/gfx/env/desup.tga" "$CS/gfx/env/Desup.tga"

# R10 already embeds/rebuilds the corrupt SNOW faces below.  Keep those payloads
# from the original R10 script if available on the live tree; otherwise use
# the valid uppercase faces already present in the user's build.
python3 - "$CS/gfx/env" <<'PYSNOW'
from pathlib import Path
import shutil,sys
d=Path(sys.argv[1])

def good(p):
    try:
        b=p.read_bytes()[:64].lstrip().lower()
        return p.stat().st_size>1024 and not b.startswith((b'<!doctype',b'<html'))
    except Exception:
        return False

# In img(5).zip SNOWdn/SNOWft/SNOWup are valid; snowbk/snowlf/snowrt are HTML.
# Reconstruct missing faces without ever leaving an HTML file in place.
mapping={
    'snowbk.tga':'SNOWft.tga',
    'snowlf.tga':'SNOWdn.tga',
    'snowrt.tga':'SNOWup.tga',
}
for dstname,srcname in mapping.items():
    dst=d/dstname
    if good(dst):
        continue
    src=d/srcname
    if not good(src):
        raise SystemExit(f'[ERROR] no valid SNOW fallback {src}')
    shutil.copy2(src,dst)
    print('[OK] repaired',dstname,'from',srcname)

# Ensure both common case variants resolve on Linux/nginx.
for face in ('bk','dn','ft','lf','rt','up'):
    low=d/f'snow{face}.tga'
    up=d/f'SNOW{face}.tga'
    if good(low) and not good(up):
        shutil.copy2(low,up)
    elif good(up) and not good(low):
        shutil.copy2(up,low)
PYSNOW

# Several map description files in img(5).zip are literally the HYPER-HOST
# "Домен не настроен" page.  They are referenced by .res and can be downloaded
# by a fresh client, so replace only that exact error page with harmless text.
python3 - "$CS" <<'PYMAPTXT'
from pathlib import Path
import sys
cs=Path(sys.argv[1])
fixed=[]
for p in (cs/'maps').glob('*.txt'):
    try:
        raw=p.read_bytes()
    except OSError:
        continue
    low=raw[:1024].lower()
    if b'<!doctype html' in low and ('Домен не настроен'.encode('utf-8') in raw or b'<title>' in low):
        p.write_text(
            f'OLD ZOMBIE\nMap: {p.stem}\n',
            encoding='utf-8'
        )
        fixed.append(p.name)
print('[OK] repaired HTML map TXT:', ', '.join(fixed) if fixed else 'none')
PYMAPTXT

echo "[OK] des/SNOW skybox recovery completed"

echo "[5/12] Canonicalizing balrogm4_fire.wav..."
BALROG_
printf '%s' "$BALROG_WAV" | base64 -d >"$CS/sound/oldz_admin_r11/balrogm4_fire.wav"
chmod 0644 "$CS/sound/oldz_admin_r11/balrogm4_fire.wav"

echo "[6/12] Fixing oldz_akblood_vip runtime-error flood..."
AK_
printf '%s' "$AK_SOURCE" | base64 -d >"$AMXX/scripting/oldz_akblood_vip.sma"
COMP="$AMXX/scripting/amxxpc"
if [[ -f "$COMP" ]]; then
 chmod +x "$COMP" "$AMXX/scripting/amxxpc32.so" 2>/dev/null || true; mkdir -p "$AMXX/scripting/compiled"
 set +e; (cd "$AMXX/scripting" && ./amxxpc oldz_akblood_vip.sma -ocompiled/oldz_akblood_vip.amxx) >"$BACKUP/akblood_compile.log" 2>&1; AKRC=$?; set -e
 if [[ $AKRC -eq 0 && -s "$AMXX/scripting/compiled/oldz_akblood_vip.amxx" ]]; then
  install -m 0644 "$AMXX/scripting/compiled/oldz_akblood_vip.amxx" "$AMXX/plugins/oldz_akblood_vip.amxx"; echo "[OK] AK Blood compiled"
 else
  echo "[WARN] compiler failed; disabling only oldz_akblood_vip.amxx"; tail -n 30 "$BACKUP/akblood_compile.log" || true
  sed -i -E 's/^([[:space:]]*oldz_akblood_vip\.amxx.*)$/; HYPER-HOST R10 compile fallback disabled: \1/' "$PLUGINS"
 fi
fi

echo "[7/12] Quarantining obsolete FastDL helper scripts..."
for x in install_fastdl_24.sh verify_fastdl.sh nginx_fastdl_24.conf nginx_fastdl_BINARY_ONLY.conf; do if [[ -e "$CS/$x" ]]; then chmod a-x "$CS/$x" 2>/dev/null || true; mv -f "$CS/$x" "$CS/$x.OBSOLETE_R10"; fi; done

echo "[8/12] Patching HYPER-HOST FastDL backend permanently..."
PATCHER="$(mktemp)"; printf '%s' '' | base64 -d >"$PATCHER"
CTL_SRC="$REPO/cs16-panel/bin/hyper-cs16-ctl"; CTL_LIVE="/usr/local/sbin/hyper-cs16-ctl"
python3 "$PATCHER" "$CTL_SRC" "$CTL_LIVE"; python3 -m py_compile "$CTL_SRC" "$CTL_LIVE"; install -m 0755 "$CTL_SRC" "$CTL_LIVE"; rm -f "$PATCHER"

echo "[9/12] Strict nginx FastDL: missing file = 404, never HTML..."
PUBLIC_IP="$(python3 - <<'PYIP'
import json
try:
 d=json.load(open('/etc/hyper-cs16/runtime.json',encoding='utf-8')); print(d.get('public_ip') or '90.189.208.25')
except Exception: print('90.189.208.25')
PYIP
)"
NGDIR="/etc/nginx/hyper-host-managed"; if ! nginx -T 2>&1 | grep -q '/etc/nginx/hyper-host-managed/'; then NGDIR="/etc/nginx/conf.d"; fi
mkdir -p "$NGDIR"; NG="$NGDIR/00-hyper-cs16-fastdl.conf"; backup_file "$NG"
cat >"$NG" <<EOF
server {
    listen 80;
    server_name ${PUBLIC_IP};
    access_log /var/log/nginx/hyper-cs16-fastdl-access.log combined;
    error_log /var/log/nginx/hyper-cs16-fastdl-error.log warn;
    location ^~ /fastdl/ {
        root /srv/hyper-cs16;
        try_files \$uri =404;
        autoindex off;
        gzip off;
        sendfile on;
        tcp_nopush on;
        default_type application/octet-stream;
        add_header X-Hyper-FastDL "R10.1" always;
        add_header Cache-Control "public, max-age=86400" always;
    }
    location / { return 404; }
}
EOF
if ! nginx -t; then echo "[ERROR] nginx config failed"; exit 5; fi
systemctl reload nginx

echo "[10/12] Validating source assets..."
python3 - "$CS" <<'PYVAL'
from pathlib import Path
import sys
root=Path(sys.argv[1]); bad=[]
for p in root.rglob('*'):
 if not p.is_file(): continue
 ext=p.suffix.lower()
 if ext not in {'.bsp','.mdl','.spr','.wav','.wad','.tga','.bmp'}: continue
 b=p.read_bytes()[:32]; low=b.lstrip().lower(); err=''
 if low.startswith(b'<!doctype') or low.startswith(b'<html'): err='HTML masquerading as asset'
 elif ext=='.bsp' and (len(b)<4 or int.from_bytes(b[:4],'little')!=30): err='bad BSP'
 elif ext=='.spr' and b[:4]!=b'IDSP': err='bad SPR'
 elif ext=='.wav' and not (b[:4]==b'RIFF' and b[8:12]==b'WAVE'): err='bad WAV'
 elif ext=='.wad' and b[:4] not in (b'WAD2',b'WAD3'): err='bad WAD'
 elif ext=='.mdl' and not (b[:4] in (b'IDST',b'IDSQ') or (len(b)>=4 and int.from_bytes(b[:4],'little')==30)): err='bad MDL'
 if err: bad.append((p.relative_to(root).as_posix(),err,p.stat().st_size))
if bad:
 print('[ERROR] invalid assets remain:'); [print(' ',x) for x in bad[:80]]; raise SystemExit(6)
print('[OK] source asset validation passed')
PYVAL

echo "[11/12] Atomic FastDL rebuild..."
"$CTL_LIVE" fastdl-sync "$SID"
SRC_MAP="$CS/maps/zm_toxic_house.bsp"
if [[ -f "$SRC_MAP" ]]; then
 SRC_HASH="$(sha256sum "$SRC_MAP" | awk '{print $1}')"; TMP_MAP="$(mktemp)"
 HTTP_CODE="$(curl -sS -H "Host: $PUBLIC_IP" -o "$TMP_MAP" -w '%{http_code}' "http://127.0.0.1/fastdl/${SID}/maps/zm_toxic_house.bsp")"; HTTP_HASH="$(sha256sum "$TMP_MAP" | awk '{print $1}')"; rm -f "$TMP_MAP"
 echo "toxic_house HTTP=$HTTP_CODE source=$SRC_HASH http=$HTTP_HASH"; [[ "$HTTP_CODE" == 200 && "$SRC_HASH" == "$HTTP_HASH" ]] || { echo '[ERROR] HTTP map mismatch'; exit 7; }
fi
TMP404="$(mktemp)"; CODE404="$(curl -sS -H "Host: $PUBLIC_IP" -o "$TMP404" -w '%{http_code}' "http://127.0.0.1/fastdl/${SID}/__r10_missing_test__.bsp")"; BODY404="$(head -c 64 "$TMP404" 2>/dev/null || true)"; rm -f "$TMP404"
echo "missing-test HTTP=$CODE404 body=$(printf %q "$BODY404")"; [[ "$CODE404" == 404 ]] || { echo '[ERROR] missing file is not a real 404'; exit 8; }

echo "[12/12] Starting server and proving sv_downloadurl survives..."
systemctl reset-failed "$SERVICE" 2>/dev/null || true; systemctl start "$SERVICE"
for _ in $(seq 1 60); do systemctl is-active --quiet "$SERVICE" && break; sleep 1; done; sleep 4
for cmd in 'sv_allowdownload 1' 'sv_allowupload 0' 'sv_send_resources 1' 'sv_allow_dlfile 0' "sv_downloadurl \"$URL\""; do "$CTL_LIVE" rcon "$SID" "$cmd" >/dev/null 2>&1 || true; done
sleep 5; echo "--- sv_downloadurl after 5 sec ---"; DL="$($CTL_LIVE rcon "$SID" 'sv_downloadurl' 2>/dev/null || true)"; echo "$DL"
if ! printf '%s' "$DL" | grep -Fq "$URL"; then echo "[ERROR] sv_downloadurl was cleared again"; grep -nEi '^[[:space:]]*(oldz_safe_download_r8|oldz_download_guard)\.amxx' "$PLUGINS" || true; exit 9; fi

echo "--- version (R10 does not change engine) ---"; "$CTL_LIVE" rcon "$SID" version 2>/dev/null || true
: > /var/log/nginx/hyper-cs16-fastdl-access.log 2>/dev/null || true
cleanup_timer; trap - EXIT; rm -rf "$TMP_PAYLOAD"
echo
echo "================================================================="
echo " [SUCCESS] OLD ZOMBIE FASTDL RECOVERY R10.1 APPLIED"
echo "================================================================="
echo "CLIENT ONE-TIME CLEANUP REQUIRED because bad HTML/map files may already be cached:"
echo "Delete already-downloaded maps/zm_toxic_house.bsp and bad gfx/env files from BOTH cstrike and cstrike_downloads on the test PC, then reconnect."
echo
echo "After reconnect:"
echo "grep '/fastdl/${SID}/' /var/log/nginx/hyper-cs16-fastdl-access.log | tail -n 100"
echo "There MUST be HTTP GET lines."
echo "Backup: $BACKUP"
